"""A PreToolUse hook that blocks destructive commands, and a linter for skill and subagent files.

Claude Code starts a hook as a process, writes one JSON event to its standard input and reads the answer from its exit code, its
standard output and its standard error. Exit code 2 blocks the call and the standard error is the reason; exit code 0 with a JSON
`permissionDecision` answers in a structured way; exit code 0 with nothing printed gives no opinion. This file is such a hook (run it
with --hook) and a demonstration (run it plain). The event and output shapes are those of the Claude Code hooks reference, read on
2026-10-03. The command check normalises what a prefix rule such as `Bash(git push *)` would miss: another form of the same command.
"""
import logging
import json
import re
import shlex
import sys

from miniyaml import split_frontmatter

log = logging.getLogger(__name__)

PROTECTED = (".env", "package-lock.json", ".git/")


def _git_subcommand(args):
    i = 0
    while i < len(args):
        if args[i] in ("-C", "-c", "--git-dir", "--work-tree"):
            i += 2
        elif args[i].startswith("-"):
            i += 1
        else:
            return args[i]
    return None


def dangerous(command):
    """The reason a command is refused, or None. Looks through compound commands, `sh -c`, env assignments, paths and git options."""
    for part in re.split(r"&&|\|\||;|\||&|\n", command):
        try:
            words = shlex.split(part)
        except ValueError:
            return "a command that cannot be parsed is not run unreviewed"
        while words and re.fullmatch(r"\w+=\S*", words[0]):
            words = words[1:]
        if not words:
            continue
        program, args = words[0].rsplit("/", 1)[-1], words[1:]
        if program in ("sh", "bash", "zsh") and "-c" in args and args.index("-c") + 1 < len(args):
            inner = dangerous(args[args.index("-c") + 1])
            if inner:
                return inner
        if program == "git" and _git_subcommand(args) == "push":
            return "nothing is pushed from an agent"
        short = "".join(a[1:] for a in args if a.startswith("-") and not a.startswith("--"))
        recursive, force = "r" in short or "R" in short or "--recursive" in args, "f" in short or "--force" in args
        if program == "rm" and recursive and force:
            return "a recursive forced delete is not run from an agent"
    return None


def pre_tool_use(event):
    """(exit code, standard output, standard error) for one PreToolUse event."""
    tool, tool_input = event["tool_name"], event.get("tool_input", {})
    if tool == "Bash":
        reason = dangerous(tool_input.get("command", ""))
        if reason:
            out = {"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": reason}}
            return 0, json.dumps(out), ""
    if tool in ("Edit", "Write", "MultiEdit"):
        path = tool_input.get("file_path", "").replace("\\", "/")
        for pattern in PROTECTED:
            if pattern in path:
                return 2, "", f"Blocked: {path} matches protected pattern '{pattern}'"
    return 0, "", ""


# --- linting the files that configure Claude Code -----------------------------------------------------------------------------

SIDE_EFFECTS = re.compile(r"\b(deploy|publish|delete|commit|push|merge)\b", re.I)


def lint_skill(text):
    fm, _ = split_frontmatter(text)
    findings = []
    desc = str(fm.get("description") or "")
    if not desc:
        findings.append("description is missing: Claude uses it to decide when to load the skill")
    if len(desc) + len(str(fm.get("when_to_use") or "")) > 1536:
        findings.append("description and when_to_use together exceed 1,536 characters and are cut")
    if SIDE_EFFECTS.search(f"{fm.get('name', '')} {desc}") and fm.get("disable-model-invocation") is not True:
        findings.append("a skill with side effects should set disable-model-invocation: true")
    allowed = fm.get("allowed-tools")
    if allowed and "Bash" in str(allowed).replace(",", " ").split():
        findings.append("allowed-tools names bare Bash: pre-approve a pattern such as Bash(git add *) instead")
    return findings


def lint_agent(text):
    fm, _ = split_frontmatter(text)
    findings = [f"{k} is required" for k in ("name", "description") if not fm.get(k)]
    if "tools" not in fm:
        findings.append("tools is omitted: the subagent inherits every tool")
    if fm.get("memory") is not None and fm["memory"] not in ("user", "project", "local"):
        findings.append("memory must be user, project or local")
    if fm.get("permissionMode") == "bypassPermissions":
        findings.append("permissionMode bypassPermissions skips every prompt in this subagent")
    return findings


SKILL = "---\nname: deploy\ndescription: Deploy the service to production\nallowed-tools: Bash\n---\nRun the release script.\n"
AGENT = "---\nname: reviewer\ndescription: Reviews a diff for bugs\nmemory: team\n---\nYou review code.\n"


def demo():
    events = [("Bash", {"command": "git push origin main"}), ("Bash", {"command": "git -C . push origin main"}), ("Bash", {"command": "bash -c 'rm -rf build'"}),
              ("Bash", {"command": "ls && git status"}), ("Bash", {"command": "rm build/old.txt"}), ("Edit", {"file_path": "/work/app/.env"}), ("Edit", {"file_path": "/work/app/main.py"})]
    for tool, tool_input in events:
        code, out, err = pre_tool_use({"hook_event_name": "PreToolUse", "tool_name": tool, "tool_input": tool_input})
        shown = f"deny (exit 0, JSON): {json.loads(out)['hookSpecificOutput']['permissionDecisionReason']}" if out else f"block (exit 2): {err}" if code == 2 else "no decision (exit 0)"
        print(f"{tool} {next(iter(tool_input.values()))!r} -> {shown}")
    print("skill findings:", lint_skill(SKILL))
    print("agent findings:", lint_agent(AGENT))


if __name__ == "__main__":
    if "--hook" in sys.argv:
        code, out, err = pre_tool_use(json.load(sys.stdin))
        sys.stdout.write(out)
        sys.stderr.write(err)
        sys.exit(code)
    demo()

// A PreToolUse hook that blocks destructive commands, and a linter for skill and subagent files.
//
// Claude Code starts a hook as a process, writes one JSON event to its standard input and reads the answer from its exit code, its
// standard output and its standard error. Exit code 2 blocks the call and the standard error is the reason; exit code 0 with a JSON
// `permissionDecision` answers in a structured way; exit code 0 with nothing printed gives no opinion. This file is such a hook (run it
// with --hook) and a demonstration (run it plain). The event and output shapes are those of the Claude Code hooks reference, read on
// 2026-10-03. The command check normalises what a prefix rule such as `Bash(git push *)` would miss: another form of the same command.
import { readFileSync } from "node:fs";
import { splitFrontmatter } from "./miniyaml.ts";
import { logger } from "./logger.ts";
const log = logger("hook_gate");

const PROTECTED = [".env", "package-lock.json", ".git/"];

/** The words of a shell command, with quotes and backslashes read the way a POSIX shell reads them. */
function shellSplit(text: string): string[] {
  const words: string[] = [];
  let cur = "";
  let inWord = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === "'") {
      const end = text.indexOf("'", i + 1);
      if (end < 0) throw new Error("No closing quotation");
      cur += text.slice(i + 1, end);
      i = end;
      inWord = true;
    } else if (c === '"') {
      i++;
      while (i < text.length && text[i] !== '"') {
        if (text[i] === "\\" && i + 1 < text.length && '"\\$`'.includes(text[i + 1])) i++;
        cur += text[i++];
      }
      if (i >= text.length) throw new Error("No closing quotation");
      inWord = true;
    } else if (c === "\\" && i + 1 < text.length) {
      cur += text[++i];
      inWord = true;
    } else if (/\s/.test(c)) {
      if (inWord) words.push(cur);
      cur = "";
      inWord = false;
    } else {
      cur += c;
      inWord = true;
    }
  }
  if (inWord) words.push(cur);
  return words;
}

function gitSubcommand(args: string[]): string | null {
  let i = 0;
  while (i < args.length) {
    if (["-C", "-c", "--git-dir", "--work-tree"].includes(args[i])) i += 2;
    else if (args[i].startsWith("-")) i += 1;
    else return args[i];
  }
  return null;
}

/** The reason a command is refused, or null. Looks through compound commands, `sh -c`, env assignments, paths and git options. */
export function dangerous(command: string): string | null {
  for (const part of command.split(/&&|\|\||;|\||&|\n/)) {
    let words: string[];
    try {
      words = shellSplit(part);
    } catch {
      return "a command that cannot be parsed is not run unreviewed";
    }
    while (words.length && /^\w+=\S*$/.test(words[0])) words = words.slice(1);
    if (!words.length) continue;
    const program = words[0].split("/").at(-1) as string;
    const args = words.slice(1);
    if (["sh", "bash", "zsh"].includes(program) && args.includes("-c") && args.indexOf("-c") + 1 < args.length) {
      const inner = dangerous(args[args.indexOf("-c") + 1]);
      if (inner) return inner;
    }
    if (program === "git" && gitSubcommand(args) === "push") return "nothing is pushed from an agent";
    const short = args.filter((a) => a.startsWith("-") && !a.startsWith("--")).map((a) => a.slice(1)).join("");
    const recursive = short.includes("r") || short.includes("R") || args.includes("--recursive");
    const force = short.includes("f") || args.includes("--force");
    if (program === "rm" && recursive && force) return "a recursive forced delete is not run from an agent";
  }
  return null;
}

/** [exit code, standard output, standard error] for one PreToolUse event. */
export function preToolUse(event: any): [number, string, string] {
  const tool = event.tool_name;
  const toolInput = event.tool_input ?? {};
  if (tool === "Bash") {
    const reason = dangerous(toolInput.command ?? "");
    if (reason) {
      const out = { hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: reason } };
      return [0, JSON.stringify(out), ""];
    }
  }
  if (["Edit", "Write", "MultiEdit"].includes(tool)) {
    const path = String(toolInput.file_path ?? "").replaceAll("\\", "/");
    for (const pattern of PROTECTED) if (path.includes(pattern)) return [2, "", `Blocked: ${path} matches protected pattern '${pattern}'`];
  }
  return [0, "", ""];
}

// --- linting the files that configure Claude Code -------------------------------------------------------------------------------

const SIDE_EFFECTS = /\b(deploy|publish|delete|commit|push|merge)\b/i;

export function lintSkill(text: string): string[] {
  const [fm] = splitFrontmatter(text);
  const findings: string[] = [];
  const desc = String(fm.description ?? "");
  if (!desc) findings.push("description is missing: Claude uses it to decide when to load the skill");
  if (desc.length + String(fm.when_to_use ?? "").length > 1536) findings.push("description and when_to_use together exceed 1,536 characters and are cut");
  if (SIDE_EFFECTS.test(`${fm.name ?? ""} ${desc}`) && fm["disable-model-invocation"] !== true) findings.push("a skill with side effects should set disable-model-invocation: true");
  const allowed = fm["allowed-tools"];
  if (allowed && String(allowed).replaceAll(",", " ").split(/\s+/).includes("Bash")) findings.push("allowed-tools names bare Bash: pre-approve a pattern such as Bash(git add *) instead");
  return findings;
}

export function lintAgent(text: string): string[] {
  const [fm] = splitFrontmatter(text);
  const findings = ["name", "description"].filter((k) => !fm[k]).map((k) => `${k} is required`);
  if (!("tools" in fm)) findings.push("tools is omitted: the subagent inherits every tool");
  if (fm.memory != null && !["user", "project", "local"].includes(String(fm.memory))) findings.push("memory must be user, project or local");
  if (fm.permissionMode === "bypassPermissions") findings.push("permissionMode bypassPermissions skips every prompt in this subagent");
  return findings;
}

const SKILL = "---\nname: deploy\ndescription: Deploy the service to production\nallowed-tools: Bash\n---\nRun the release script.\n";
const AGENT = "---\nname: reviewer\ndescription: Reviews a diff for bugs\nmemory: team\n---\nYou review code.\n";

/** A string written the way Python writes it, so both languages show the same output. */
function pyRepr(s: string): string {
  return s.includes("'") && !s.includes('"') ? `"${s}"` : `'${s}'`;
}

function pyList(items: string[]): string {
  return `[${items.map(pyRepr).join(", ")}]`;
}

function demo() {
  const events: Array<[string, Record<string, string>]> = [["Bash", { command: "git push origin main" }], ["Bash", { command: "git -C . push origin main" }], ["Bash", { command: "bash -c 'rm -rf build'" }],
    ["Bash", { command: "ls && git status" }], ["Bash", { command: "rm build/old.txt" }], ["Edit", { file_path: "/work/app/.env" }], ["Edit", { file_path: "/work/app/main.py" }]];
  for (const [tool, toolInput] of events) {
    const [code, out, err] = preToolUse({ hook_event_name: "PreToolUse", tool_name: tool, tool_input: toolInput });
    const shown = out ? `deny (exit 0, JSON): ${JSON.parse(out).hookSpecificOutput.permissionDecisionReason}` : code === 2 ? `block (exit 2): ${err}` : "no decision (exit 0)";
    console.log(`${tool} ${pyRepr(Object.values(toolInput)[0])} -> ${shown}`);
  }
  console.log("skill findings:", pyList(lintSkill(SKILL)));
  console.log("agent findings:", pyList(lintAgent(AGENT)));
}

if (import.meta.main) {
  if (process.argv.includes("--hook")) {
    const [code, out, err] = preToolUse(JSON.parse(readFileSync(0, "utf8")));
    process.stdout.write(out);
    process.stderr.write(err);
    process.exitCode = code;
  } else demo();
}

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * A PreToolUse hook that blocks destructive commands, and a linter for skill and subagent files.
 *
 * <p>Claude Code starts a hook as a process, writes one JSON event to its standard input and reads the answer from its exit code, its
 * standard output and its standard error. Exit code 2 blocks the call and the standard error is the reason; exit code 0 with a JSON
 * `permissionDecision` answers in a structured way; exit code 0 with nothing printed gives no opinion. This file is such a hook (run it
 * with --hook) and a demonstration (run it plain). The event and output shapes are those of the Claude Code hooks reference, read on
 * 2026-10-03. The command check normalises what a prefix rule such as `Bash(git push *)` would miss: another form of the same command.
 * The front matter of the skill and subagent files is YAML, read with Jackson.
 */
public final class HookGate {
    private static final System.Logger LOG = System.getLogger(HookGate.class.getName());
    static final List<String> PROTECTED = List.of(".env", "package-lock.json", ".git/");
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final ObjectMapper YAML = new ObjectMapper(new YAMLFactory());

    /** What the hook process answers: the exit code, standard output and standard error. */
    record Answer(int code, String out, String err) {}

    /** The words of a command line as a POSIX shell would split them (quotes and backslashes); a bad quote is an error. */
    static List<String> shlexSplit(String s) {
        List<String> words = new ArrayList<>();
        StringBuilder word = null;
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i++);
            if (Character.isWhitespace(c)) {
                if (word != null) { words.add(word.toString()); word = null; }
                continue;
            }
            if (word == null) word = new StringBuilder();
            if (c == '\\') {
                if (i >= s.length()) throw new IllegalArgumentException("No escaped character");
                word.append(s.charAt(i++));
            } else if (c == '\'') {
                int end = s.indexOf('\'', i);
                if (end < 0) throw new IllegalArgumentException("No closing quotation");
                word.append(s, i, end);
                i = end + 1;
            } else if (c == '"') {
                while (true) {
                    if (i >= s.length()) throw new IllegalArgumentException("No closing quotation");
                    char d = s.charAt(i++);
                    if (d == '"') break;
                    if (d == '\\' && i < s.length() && "\"\\$`\n".indexOf(s.charAt(i)) >= 0) d = s.charAt(i++);
                    word.append(d);
                }
            } else {
                word.append(c);
            }
        }
        if (word != null) words.add(word.toString());
        return words;
    }

    private static String gitSubcommand(List<String> args) {
        int i = 0;
        while (i < args.size()) {
            String a = args.get(i);
            if (List.of("-C", "-c", "--git-dir", "--work-tree").contains(a)) i += 2;
            else if (a.startsWith("-")) i += 1;
            else return a;
        }
        return null;
    }

    /** The reason a command is refused, or null. Looks through compound commands, `sh -c`, env assignments, paths and git options. */
    static String dangerous(String command) {
        for (String part : command.split("&&|\\|\\||;|\\||&|\n")) {
            List<String> words;
            try {
                words = shlexSplit(part);
            } catch (IllegalArgumentException e) {
                return "a command that cannot be parsed is not run unreviewed";
            }
            int skip = 0;
            while (skip < words.size() && words.get(skip).matches("\\w+=\\S*")) skip++;
            words = words.subList(skip, words.size());
            if (words.isEmpty()) continue;
            String program = words.get(0).substring(words.get(0).lastIndexOf('/') + 1);
            List<String> args = words.subList(1, words.size());
            int dashC = args.indexOf("-c");
            if (List.of("sh", "bash", "zsh").contains(program) && dashC >= 0 && dashC + 1 < args.size()) {
                String inner = dangerous(args.get(dashC + 1));
                if (inner != null) return inner;
            }
            if (program.equals("git") && "push".equals(gitSubcommand(args))) return "nothing is pushed from an agent";
            String shortFlags = args.stream().filter(a -> a.startsWith("-") && !a.startsWith("--")).map(a -> a.substring(1)).collect(Collectors.joining());
            boolean recursive = shortFlags.contains("r") || shortFlags.contains("R") || args.contains("--recursive");
            boolean force = shortFlags.contains("f") || args.contains("--force");
            if (program.equals("rm") && recursive && force) return "a recursive forced delete is not run from an agent";
        }
        return null;
    }

    /** The answer for one PreToolUse event. */
    @SuppressWarnings("unchecked")
    static Answer preToolUse(Map<String, Object> event) throws IOException {
        String tool = (String) event.get("tool_name");
        Map<String, Object> toolInput = (Map<String, Object>) event.getOrDefault("tool_input", Map.of());
        if (tool.equals("Bash")) {
            String reason = dangerous((String) toolInput.getOrDefault("command", ""));
            if (reason != null) {
                Map<String, Object> specific = new LinkedHashMap<>();
                specific.put("hookEventName", "PreToolUse");
                specific.put("permissionDecision", "deny");
                specific.put("permissionDecisionReason", reason);
                return new Answer(0, JSON.writeValueAsString(Map.of("hookSpecificOutput", specific)), "");
            }
        }
        if (List.of("Edit", "Write", "MultiEdit").contains(tool)) {
            String path = ((String) toolInput.getOrDefault("file_path", "")).replace("\\", "/");
            for (String pattern : PROTECTED) {
                if (path.contains(pattern)) return new Answer(2, "", "Blocked: " + path + " matches protected pattern '" + pattern + "'");
            }
        }
        return new Answer(0, "", "");
    }

    // --- linting the files that configure Claude Code -------------------------------------------------------------------

    private static final Pattern SIDE_EFFECTS = Pattern.compile("\\b(deploy|publish|delete|commit|push|merge)\\b", Pattern.CASE_INSENSITIVE);
    private static final Pattern FRONTMATTER = Pattern.compile("^---\\n(.*?)\\n---\\n?(.*)$", Pattern.DOTALL);

    /** The front matter of a Markdown file that starts with a --- block; an empty map when it has none. */
    @SuppressWarnings("unchecked")
    static Map<String, Object> frontmatter(String text) throws IOException {
        Matcher m = FRONTMATTER.matcher(text);
        if (!m.matches()) return Map.of();
        Map<String, Object> fm = YAML.readValue(m.group(1), LinkedHashMap.class);
        return fm == null ? Map.of() : fm;
    }

    private static String text(Object o) {
        return o == null ? "" : String.valueOf(o);
    }

    static List<String> lintSkill(String text) throws IOException {
        Map<String, Object> fm = frontmatter(text);
        List<String> findings = new ArrayList<>();
        String desc = text(fm.get("description"));
        if (desc.isEmpty()) findings.add("description is missing: Claude uses it to decide when to load the skill");
        if (desc.length() + text(fm.get("when_to_use")).length() > 1536) findings.add("description and when_to_use together exceed 1,536 characters and are cut");
        if (SIDE_EFFECTS.matcher(text(fm.getOrDefault("name", "")) + " " + desc).find() && !Boolean.TRUE.equals(fm.get("disable-model-invocation"))) {
            findings.add("a skill with side effects should set disable-model-invocation: true");
        }
        Object allowed = fm.get("allowed-tools");
        if (allowed != null && !text(allowed).isEmpty() && List.of(text(allowed).replace(",", " ").trim().split("\\s+")).contains("Bash")) {
            findings.add("allowed-tools names bare Bash: pre-approve a pattern such as Bash(git add *) instead");
        }
        return findings;
    }

    static List<String> lintAgent(String text) throws IOException {
        Map<String, Object> fm = frontmatter(text);
        List<String> findings = new ArrayList<>();
        for (String k : List.of("name", "description")) if (text(fm.get(k)).isEmpty()) findings.add(k + " is required");
        if (!fm.containsKey("tools")) findings.add("tools is omitted: the subagent inherits every tool");
        if (fm.get("memory") != null && !List.of("user", "project", "local").contains(fm.get("memory"))) findings.add("memory must be user, project or local");
        if ("bypassPermissions".equals(fm.get("permissionMode"))) findings.add("permissionMode bypassPermissions skips every prompt in this subagent");
        return findings;
    }

    static final String SKILL = "---\nname: deploy\ndescription: Deploy the service to production\nallowed-tools: Bash\n---\nRun the release script.\n";
    static final String AGENT = "---\nname: reviewer\ndescription: Reviews a diff for bugs\nmemory: team\n---\nYou review code.\n";

    /** Python's repr of strings and lists of strings, so every language of the course prints the same text. */
    static String py(Object v) {
        if (v instanceof List<?> l) return l.stream().map(HookGate::py).collect(Collectors.joining(", ", "[", "]"));
        String s = String.valueOf(v);
        String q = s.contains("'") && !s.contains("\"") ? "\"" : "'";
        return q + s.replace("\\", "\\\\").replace("\n", "\\n").replace(q, "\\" + q) + q;
    }

    @SuppressWarnings("unchecked")
    static void demo() throws IOException {
        List<Object[]> events = List.of(
            new Object[] {"Bash", "command", "git push origin main"}, new Object[] {"Bash", "command", "git -C . push origin main"},
            new Object[] {"Bash", "command", "bash -c 'rm -rf build'"}, new Object[] {"Bash", "command", "ls && git status"},
            new Object[] {"Bash", "command", "rm build/old.txt"}, new Object[] {"Edit", "file_path", "/work/app/.env"},
            new Object[] {"Edit", "file_path", "/work/app/main.py"});
        for (Object[] e : events) {
            Map<String, Object> event = Map.of("hook_event_name", "PreToolUse", "tool_name", e[0], "tool_input", Map.of((String) e[1], e[2]));
            Answer a = preToolUse(event);
            String shown;
            if (!a.out().isEmpty()) {
                Map<String, Object> specific = (Map<String, Object>) JSON.readValue(a.out(), Map.class).get("hookSpecificOutput");
                shown = "deny (exit 0, JSON): " + specific.get("permissionDecisionReason");
            } else {
                shown = a.code() == 2 ? "block (exit 2): " + a.err() : "no decision (exit 0)";
            }
            System.out.println(e[0] + " " + py(e[2]) + " -> " + shown);
        }
        System.out.println("skill findings: " + py(lintSkill(SKILL)));
        System.out.println("agent findings: " + py(lintAgent(AGENT)));
    }

    public static void main(String[] args) throws Exception {
        if (List.of(args).contains("--hook")) {
            Answer a = preToolUse(JSON.readValue(System.in, LinkedHashMap.class));
            System.out.print(a.out());
            System.err.print(a.err());
            System.out.flush();
            System.err.flush();
            System.exit(a.code());
        }
        demo();
    }
}

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import kotlin.system.exitProcess

private val log = System.getLogger("hook_gate")

/**
 * A PreToolUse hook that blocks destructive commands, and a linter for skill and subagent files.
 *
 * Claude Code starts a hook as a process, writes one JSON event to its standard input and reads the answer from its exit code, its
 * standard output and its standard error. Exit code 2 blocks the call and the standard error is the reason; exit code 0 with a JSON
 * `permissionDecision` answers in a structured way; exit code 0 with nothing printed gives no opinion. This file is such a hook (run it
 * with --hook) and a demonstration (run it plain). The event and output shapes are those of the Claude Code hooks reference, read on
 * 2026-10-03. The command check normalises what a prefix rule such as `Bash(git push *)` would miss: another form of the same command.
 * The front matter of the skill and subagent files is YAML, read with Jackson.
 */
val PROTECTED = listOf(".env", "package-lock.json", ".git/")
private val JSON = ObjectMapper()
private val YAML = ObjectMapper(YAMLFactory())

/** What the hook process answers: the exit code, standard output and standard error. */
data class Answer(val code: Int, val out: String, val err: String)

/** The words of a command line as a POSIX shell would split them (quotes and backslashes); a bad quote is an error. */
fun shlexSplit(s: String): List<String> {
    val words = mutableListOf<String>()
    var word: StringBuilder? = null
    var i = 0
    while (i < s.length) {
        val c = s[i++]
        if (c.isWhitespace()) {
            word?.let { words += it.toString() }
            word = null
            continue
        }
        val w = word ?: StringBuilder().also { word = it }
        when (c) {
            '\\' -> {
                require(i < s.length) { "No escaped character" }
                w.append(s[i++])
            }
            '\'' -> {
                val end = s.indexOf('\'', i)
                require(end >= 0) { "No closing quotation" }
                w.append(s, i, end)
                i = end + 1
            }
            '"' -> while (true) {
                require(i < s.length) { "No closing quotation" }
                var d = s[i++]
                if (d == '"') break
                if (d == '\\' && i < s.length && s[i] in "\"\\$`\n") d = s[i++]
                w.append(d)
            }
            else -> w.append(c)
        }
    }
    word?.let { words += it.toString() }
    return words
}

private fun gitSubcommand(args: List<String>): String? {
    var i = 0
    while (i < args.size) {
        val a = args[i]
        if (a in listOf("-C", "-c", "--git-dir", "--work-tree")) i += 2 else if (a.startsWith("-")) i += 1 else return a
    }
    return null
}

/** The reason a command is refused, or null. Looks through compound commands, `sh -c`, env assignments, paths and git options. */
fun dangerous(command: String): String? {
    for (part in command.split(Regex("&&|\\|\\||;|\\||&|\n"))) {
        val split = try {
            shlexSplit(part)
        } catch (e: IllegalArgumentException) {
            return "a command that cannot be parsed is not run unreviewed"
        }
        val words = split.dropWhile { Regex("""\w+=\S*""").matches(it) }
        if (words.isEmpty()) continue
        val program = words[0].substringAfterLast('/')
        val args = words.drop(1)
        val dashC = args.indexOf("-c")
        if (program in listOf("sh", "bash", "zsh") && dashC >= 0 && dashC + 1 < args.size) {
            dangerous(args[dashC + 1])?.let { return it }
        }
        if (program == "git" && gitSubcommand(args) == "push") return "nothing is pushed from an agent"
        val short = args.filter { it.startsWith("-") && !it.startsWith("--") }.joinToString("") { it.drop(1) }
        val recursive = "r" in short || "R" in short || "--recursive" in args
        val force = "f" in short || "--force" in args
        if (program == "rm" && recursive && force) return "a recursive forced delete is not run from an agent"
    }
    return null
}

/** The answer for one PreToolUse event. */
fun preToolUse(event: Map<String, Any?>): Answer {
    val tool = event["tool_name"] as String
    @Suppress("UNCHECKED_CAST") val toolInput = (event["tool_input"] ?: emptyMap<String, Any?>()) as Map<String, Any?>
    if (tool == "Bash") {
        dangerous(toolInput["command"] as String? ?: "")?.let { reason ->
            val specific = linkedMapOf("hookEventName" to "PreToolUse", "permissionDecision" to "deny", "permissionDecisionReason" to reason)
            return Answer(0, JSON.writeValueAsString(mapOf("hookSpecificOutput" to specific)), "")
        }
    }
    if (tool in listOf("Edit", "Write", "MultiEdit")) {
        val path = (toolInput["file_path"] as String? ?: "").replace("\\", "/")
        for (pattern in PROTECTED) if (pattern in path) return Answer(2, "", "Blocked: $path matches protected pattern '$pattern'")
    }
    return Answer(0, "", "")
}

// --- linting the files that configure Claude Code -----------------------------------------------------------------------------

private val SIDE_EFFECTS = Regex("""\b(deploy|publish|delete|commit|push|merge)\b""", RegexOption.IGNORE_CASE)

/** The front matter of a Markdown file that starts with a --- block; an empty map when it has none. */
@Suppress("UNCHECKED_CAST")
fun frontmatter(text: String): Map<String, Any?> {
    val m = Regex("^---\\n(.*?)\\n---\\n?(.*)$", RegexOption.DOT_MATCHES_ALL).matchEntire(text) ?: return emptyMap()
    return YAML.readValue(m.groupValues[1], LinkedHashMap::class.java) as Map<String, Any?>? ?: emptyMap()
}

private fun text(o: Any?) = o?.toString() ?: ""

fun lintSkill(text: String): List<String> {
    val fm = frontmatter(text)
    val findings = mutableListOf<String>()
    val desc = text(fm["description"])
    if (desc.isEmpty()) findings += "description is missing: Claude uses it to decide when to load the skill"
    if (desc.length + text(fm["when_to_use"]).length > 1536) findings += "description and when_to_use together exceed 1,536 characters and are cut"
    if (SIDE_EFFECTS.containsMatchIn("${text(fm["name"])} $desc") && fm["disable-model-invocation"] != true) {
        findings += "a skill with side effects should set disable-model-invocation: true"
    }
    val allowed = text(fm["allowed-tools"])
    if (allowed.isNotEmpty() && "Bash" in allowed.replace(",", " ").trim().split(Regex("\\s+"))) {
        findings += "allowed-tools names bare Bash: pre-approve a pattern such as Bash(git add *) instead"
    }
    return findings
}

fun lintAgent(text: String): List<String> {
    val fm = frontmatter(text)
    val findings = listOf("name", "description").filter { text(fm[it]).isEmpty() }.map { "$it is required" }.toMutableList()
    if ("tools" !in fm) findings += "tools is omitted: the subagent inherits every tool"
    if (fm["memory"] != null && fm["memory"] !in listOf("user", "project", "local")) findings += "memory must be user, project or local"
    if (fm["permissionMode"] == "bypassPermissions") findings += "permissionMode bypassPermissions skips every prompt in this subagent"
    return findings
}

const val SKILL = "---\nname: deploy\ndescription: Deploy the service to production\nallowed-tools: Bash\n---\nRun the release script.\n"
const val AGENT = "---\nname: reviewer\ndescription: Reviews a diff for bugs\nmemory: team\n---\nYou review code.\n"

/** Python's repr of strings and lists of strings, so every language of the course prints the same text. */
fun py(v: Any?): String {
    if (v is List<*>) return v.joinToString(", ", "[", "]") { py(it) }
    val s = v.toString()
    val q = if ("'" in s && "\"" !in s) "\"" else "'"
    return q + s.replace("\\", "\\\\").replace("\n", "\\n").replace(q, "\\" + q) + q
}

fun demo() {
    val events = listOf(
        "Bash" to ("command" to "git push origin main"), "Bash" to ("command" to "git -C . push origin main"), "Bash" to ("command" to "bash -c 'rm -rf build'"),
        "Bash" to ("command" to "ls && git status"), "Bash" to ("command" to "rm build/old.txt"), "Edit" to ("file_path" to "/work/app/.env"),
        "Edit" to ("file_path" to "/work/app/main.py"),
    )
    for ((tool, input) in events) {
        val (code, out, err) = preToolUse(mapOf("hook_event_name" to "PreToolUse", "tool_name" to tool, "tool_input" to mapOf(input)))
        val shown = when {
            out.isNotEmpty() -> "deny (exit 0, JSON): " + (JSON.readTree(out)["hookSpecificOutput"]["permissionDecisionReason"].asText())
            code == 2 -> "block (exit 2): $err"
            else -> "no decision (exit 0)"
        }
        println("$tool ${py(input.second)} -> $shown")
    }
    println("skill findings: ${py(lintSkill(SKILL))}")
    println("agent findings: ${py(lintAgent(AGENT))}")
}

fun main(args: Array<String>) {
    if ("--hook" in args) {
        @Suppress("UNCHECKED_CAST")
        val (code, out, err) = preToolUse(JSON.readValue(System.`in`, LinkedHashMap::class.java) as Map<String, Any?>)
        print(out)
        System.err.print(err)
        System.out.flush()
        System.err.flush()
        exitProcess(code)
    }
    demo()
}
